#import "HelpArticle.h"
#import "LinkSupport.h"
static UILabel *ArticleLabel(NSString *text,UIFontTextStyle style){UILabel *label=[UILabel new];label.text=text;label.numberOfLines=0;label.font=[UIFont preferredFontForTextStyle:style];label.adjustsFontForContentSizeCategory=YES;return label;}
@interface TMCArticle : UITableViewController
@property BOOL licenseLayout;
@property NSString *articleTitle;
@property NSString *subtitle;
@property NSString *symbol;
@property NSArray<NSDictionary *> *chapters;
@property NSArray<NSArray<NSDictionary *> *> *rows;
@end
@implementation TMCArticle
- (void)viewDidLoad{
 [super viewDidLoad];NSInteger theme=[NSUserDefaults.standardUserDefaults integerForKey:@"StudioTheme"];self.overrideUserInterfaceStyle=theme==1?UIUserInterfaceStyleDark:theme==2?UIUserInterfaceStyleLight:UIUserInterfaceStyleUnspecified;
 self.title=self.articleTitle;self.navigationItem.largeTitleDisplayMode=UINavigationItemLargeTitleDisplayModeNever;self.tableView.backgroundColor=UIColor.systemGroupedBackgroundColor;self.tableView.separatorStyle=UITableViewCellSeparatorStyleNone;self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=150;self.tableView.cellLayoutMarginsFollowReadableWidth=YES;
 NSMutableArray *chapters=[NSMutableArray new];for(NSDictionary *chapter in self.chapters){NSMutableArray *rows=[NSMutableArray new];NSString *content=chapter[@"text"]?:@"";for(NSString *paragraph in [content componentsSeparatedByString:@"\n\n"]){NSString *text=[paragraph stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(!text.length)continue;
 NSRegularExpression *number=[NSRegularExpression regularExpressionWithPattern:@"^([0-9]+)\\.\\s*" options:0 error:nil];NSTextCheckingResult *match=self.licenseLayout?nil:[number firstMatchInString:text options:0 range:NSMakeRange(0,text.length)];NSString *badge=match?[text substringWithRange:[match rangeAtIndex:1]]:@"";if(match)text=[text substringFromIndex:match.range.length];
 [rows addObject:@{@"text":text,@"number":badge}];}for(NSDictionary *link in chapter[@"links"]?:@[])[rows addObject:@{@"link":link}];[chapters addObject:rows];}self.rows=chapters;
 UIBarButtonItem *contents=[[UIBarButtonItem alloc] initWithImage:[UIImage systemImageNamed:@"list.bullet.rectangle"] style:UIBarButtonItemStylePlain target:self action:@selector(contents)];contents.accessibilityLabel=@"章节目录";self.navigationItem.rightBarButtonItem=contents;
}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)table{return self.chapters.count+1;}
- (NSInteger)tableView:(UITableView *)table numberOfRowsInSection:(NSInteger)section{return section?self.rows[section-1].count:1;}
- (UIView *)tableView:(UITableView *)table viewForHeaderInSection:(NSInteger)section{if(!section)return nil;UIView *view=[UIView new];UILabel *label=ArticleLabel(self.chapters[section-1][@"title"]?:@"",UIFontTextStyleHeadline);label.translatesAutoresizingMaskIntoConstraints=NO;[view addSubview:label];[NSLayoutConstraint activateConstraints:@[[label.leadingAnchor constraintEqualToAnchor:view.layoutMarginsGuide.leadingAnchor constant:4],[label.trailingAnchor constraintEqualToAnchor:view.layoutMarginsGuide.trailingAnchor constant:-4],[label.topAnchor constraintEqualToAnchor:view.topAnchor constant:18],[label.bottomAnchor constraintEqualToAnchor:view.bottomAnchor constant:-10]]];return view;}
- (CGFloat)tableView:(UITableView *)table heightForHeaderInSection:(NSInteger)section{return section?UITableViewAutomaticDimension:12;}
- (CGFloat)tableView:(UITableView *)table heightForFooterInSection:(NSInteger)section{return 12;}
- (UITableViewCell *)tableView:(UITableView *)table cellForRowAtIndexPath:(NSIndexPath *)path{
 UITableViewCell *cell=[[UITableViewCell alloc] initWithStyle:UITableViewCellStyleDefault reuseIdentifier:nil];cell.selectionStyle=UITableViewCellSelectionStyleNone;cell.backgroundColor=UIColor.secondarySystemGroupedBackgroundColor;
 UIStackView *stack=[UIStackView new];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=12;stack.translatesAutoresizingMaskIntoConstraints=NO;[cell.contentView addSubview:stack];[NSLayoutConstraint activateConstraints:@[[stack.leadingAnchor constraintEqualToAnchor:cell.contentView.layoutMarginsGuide.leadingAnchor constant:4],[stack.trailingAnchor constraintEqualToAnchor:cell.contentView.layoutMarginsGuide.trailingAnchor constant:-4],[stack.topAnchor constraintEqualToAnchor:cell.contentView.topAnchor constant:self.licenseLayout?10:18],[stack.bottomAnchor constraintEqualToAnchor:cell.contentView.bottomAnchor constant:self.licenseLayout?-10:-18]]];
 if(!path.section){UIColor *accent=[UIColor colorWithDynamicProvider:^UIColor *(UITraitCollection *trait){return trait.userInterfaceStyle==UIUserInterfaceStyleDark?[UIColor colorWithRed:.93 green:.77 blue:.52 alpha:1]:[UIColor colorWithRed:.48 green:.31 blue:.09 alpha:1];}];UIImageView *icon=[[UIImageView alloc] initWithImage:[UIImage systemImageNamed:self.symbol withConfiguration:[UIImageSymbolConfiguration configurationWithPointSize:29 weight:UIImageSymbolWeightMedium]]];icon.tintColor=accent;icon.contentMode=UIViewContentModeLeft;[icon.heightAnchor constraintEqualToConstant:42].active=YES;[stack addArrangedSubview:icon];UILabel *tag=ArticleLabel(self.licenseLayout?@"TWEAKFORGE  /  开源许可":@"TWEAKFORGE  /  使用指南",UIFontTextStyleCaption2);tag.textColor=accent;[stack addArrangedSubview:tag];UILabel *title=ArticleLabel(self.articleTitle,UIFontTextStyleTitle1);title.font=[UIFont preferredFontForTextStyle:UIFontTextStyleTitle1 compatibleWithTraitCollection:self.traitCollection];[stack addArrangedSubview:title];UILabel *subtitle=ArticleLabel(self.subtitle,UIFontTextStyleSubheadline);subtitle.textColor=UIColor.secondaryLabelColor;[stack addArrangedSubview:subtitle];return cell;}
 NSDictionary *row=self.rows[path.section-1][path.row];if(row[@"link"]){NSDictionary *link=row[@"link"];cell.selectionStyle=UITableViewCellSelectionStyleDefault;cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;UIStackView *line=[UIStackView new];line.spacing=12;line.alignment=UIStackViewAlignmentCenter;UIImageView *icon=[[UIImageView alloc] initWithImage:[UIImage systemImageNamed:@"arrow.up.right.square"]];icon.tintColor=UIColor.systemBlueColor;[icon.widthAnchor constraintEqualToConstant:22].active=YES;[line addArrangedSubview:icon];UILabel *title=ArticleLabel(link[@"title"],UIFontTextStyleSubheadline);title.textColor=UIColor.systemBlueColor;[line addArrangedSubview:title];[stack addArrangedSubview:line];NSURL *url=[NSURL URLWithString:link[@"url"]];UILabel *host=ArticleLabel(url.host?:link[@"url"],UIFontTextStyleCaption1);host.textColor=UIColor.secondaryLabelColor;[stack addArrangedSubview:host];cell.accessibilityLabel=[NSString stringWithFormat:@"%@，打开网页",link[@"title"]];return cell;}
 UIStackView *line=[UIStackView new];line.spacing=12;line.alignment=UIStackViewAlignmentTop;NSString *number=row[@"number"];if(number.length){UILabel *badge=ArticleLabel(number,UIFontTextStyleSubheadline);badge.font=[UIFont monospacedDigitSystemFontOfSize:16 weight:UIFontWeightSemibold];badge.textColor=UIColor.systemBlueColor;badge.textAlignment=NSTextAlignmentCenter;badge.backgroundColor=[UIColor.systemBlueColor colorWithAlphaComponent:.10];badge.layer.cornerRadius=10;badge.clipsToBounds=YES;[badge.widthAnchor constraintEqualToConstant:32].active=YES;[badge.heightAnchor constraintEqualToConstant:32].active=YES;[line addArrangedSubview:badge];}
 UILabel *text=ArticleLabel(@"",self.licenseLayout?UIFontTextStyleSubheadline:UIFontTextStyleBody);text.backgroundColor=UIColor.clearColor;NSMutableParagraphStyle *paragraph=[NSMutableParagraphStyle new];paragraph.lineSpacing=self.licenseLayout?3:5;paragraph.paragraphSpacing=self.licenseLayout?0:8;NSString *value=row[@"text"]?:@"";text.attributedText=[[NSAttributedString alloc] initWithString:value attributes:@{NSFontAttributeName:[UIFont preferredFontForTextStyle:self.licenseLayout?UIFontTextStyleSubheadline:UIFontTextStyleBody],NSForegroundColorAttributeName:UIColor.labelColor,NSParagraphStyleAttributeName:paragraph}];TMCEnableLinksInView(text);[line addArrangedSubview:text];[stack addArrangedSubview:line];return cell;
}
- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)path{[table deselectRowAtIndexPath:path animated:YES];if(!path.section)return;NSDictionary *link=self.rows[path.section-1][path.row][@"link"];NSURL *url=[NSURL URLWithString:link[@"url"]?:@""];if([@[@"https",@"http"] containsObject:url.scheme.lowercaseString])[UIApplication.sharedApplication openURL:url options:@{} completionHandler:nil];}
- (void)contents{UIAlertController *menu=[UIAlertController alertControllerWithTitle:@"章节目录" message:nil preferredStyle:UIAlertControllerStyleActionSheet];[self.chapters enumerateObjectsUsingBlock:^(NSDictionary *chapter,NSUInteger index,BOOL *stop){if(!self.rows[index].count)return;[menu addAction:[UIAlertAction actionWithTitle:chapter[@"title"] style:UIAlertActionStyleDefault handler:^(id action){[self.tableView scrollToRowAtIndexPath:[NSIndexPath indexPathForRow:0 inSection:index+1] atScrollPosition:UITableViewScrollPositionTop animated:!UIAccessibilityIsReduceMotionEnabled()];}]];}];[menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];menu.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItem;[self presentViewController:menu animated:YES completion:nil];}
@end
UIViewController *TMCHelpArticle(NSString *title,NSString *subtitle,NSString *symbol,NSArray *chapters){TMCArticle *article=[[TMCArticle alloc] initWithStyle:UITableViewStyleInsetGrouped];article.articleTitle=title;article.subtitle=subtitle;article.symbol=symbol;article.chapters=chapters;return article;}
UIViewController *TMCHelpTextArticle(NSString *title,NSString *text){
 NSString *path=[NSBundle.mainBundle.bundlePath stringByAppendingPathComponent:@"HelpArticles/articles.json"];NSData *data=[NSData dataWithContentsOfFile:path];NSDictionary *catalog=data?[NSJSONSerialization JSONObjectWithData:data options:0 error:nil]:nil;NSDictionary *page=catalog[title];
 if(page)return TMCHelpArticle(title,page[@"subtitle"],page[@"symbol"],page[@"sections"]);
 BOOL license=[text containsString:@"许可："]&&[text containsString:@"来源："];
 if(license){
  // Keep the bundled original intact; reflow only the presentation of hard-wrapped prose.
  NSRange split=[text rangeOfString:@"\n\n"];NSString *metadata=split.location==NSNotFound?text:[text substringToIndex:split.location];NSString *body=split.location==NSNotFound?@"":[text substringFromIndex:NSMaxRange(split)];
  NSMutableArray *parts=[NSMutableArray new];NSMutableString *current=[NSMutableString new];
  for(NSString *raw in [[body stringByReplacingOccurrencesOfString:@"\r\n" withString:@"\n"] componentsSeparatedByString:@"\n"]){
   NSString *line=[raw stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
   BOOL divider=line.length>3&&[[line stringByTrimmingCharactersInSet:[NSCharacterSet characterSetWithCharactersInString:@"=-_"]] length]==0;
   BOOL item=[[NSRegularExpression regularExpressionWithPattern:@"^(?:[0-9]+[.)]|[a-z][.)]|[*•-])\\s+" options:0 error:nil] firstMatchInString:line options:0 range:NSMakeRange(0,line.length)]!=nil;
   if(!line.length||divider||item){if(current.length){[parts addObject:[current copy]];[current setString:@""];}if(divider)continue;}
   if(line.length){if(current.length)[current appendString:@" "];[current appendString:line];}
  }
  if(current.length)[parts addObject:current];
  TMCArticle *article=(TMCArticle *)TMCHelpArticle(title,@"组件来源、使用许可与版权声明",@"checkmark.seal",@[@{@"title":@"组件信息",@"text":metadata},@{@"title":@"许可证全文",@"text":[parts componentsJoinedByString:@"\n\n"]}]);article.licenseLayout=YES;return article;
 }
 NSArray *sections=@[@{@"title":license?@"许可证与来源":@"参考内容",@"text":text?:@""}];return TMCHelpArticle(title,license?@"组件来源、使用许可与版权声明":@"相关说明与参考资料",license?@"checkmark.seal":@"doc.text",sections);
}
